quests[73388] = { id = 73388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gain New Look: Undead Ghoul", progress = "Apply a Rumble Foil to your Warcraft Rumble Mini and gain a new look!", completion = "Congratulations! Your Undead Ghoul miniature now has an extra look!" }
