quests[73864] = { id = 73864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74117] = { id = 74117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Prey", description = "Rare and dangerous creatures lurk around the creches of the Forbidden Reach. If you and your allies want to stay safe, you should hunt down these threats.", progress = "Are there still dangers roaming the land?", completion = "I'm glad you dealt with those threats. I'm sure they got what they deserved.", objectives = "Hunt down the special threats across the Forbidden Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74118] = { id = 74118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spelunking the Den", description = "Did you have a chance to visit the Skyfox Den? A very exciting place, from what I've heard. Expedition's spelunkers started surveying the cave and even installed a few grappling hooks on the ceiling, but they were scared away by violent slyverns.\n\nCan you do me a favor? Get inside the Skyfox Den, grab the abandoned gear, and check the ceiling for any hidden crevices. Who knows what could be hidden inside?", progress = "Found anything exciting there?", completion = "Well done! My research and writing never end. I'm glad you've seen what's in the den firsthand.", objectives = "Explore the Skyfox Den's ceiling using Dragonscale Expedition climbing gear inside the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74119] = { id = 74119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angler's Challenge", description = "Say, have you noticed how good the fishing is around here? Dragonskull Island seems like it would have some great spots to cast a line. \n\nWhy don't you go there and catch something for dinner? Be mindful, though. We still need to set some of our catch aside for later.", progress = "My belly's rumbling... can't wait for those fresh fish!", completion = "We'll have a feast tonight, thanks to you!", objectives = "Catch or restock fish in the Dragonskull Fishing Hole.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74120] = { id = 74120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spring Awakening", description = "If you're looking for something to do, I hear there are mages in the settlements near capital cities - Goldshire, Kharanos, Dolanaar, and Azure Watch - who have been recruiting egg hunters for help with some research they're doing. I'm not sure of the particulars, but I'm sure they'd tell you.", completion = "Yes! Yes, I think I have just the task for you...", objectives = "Talk to a Spring Collector in Goldshire, Kharanos, Dolanaar, or Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74282] = { id = 74282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Authentic Authorization", description = "The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course!\n\nIf I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans!\n\nIf you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!", progress = "Did you find anything?", completion = "What an amazing find. The mind reels. \n\nOh, and I can't wait to write about this discovery and publish our findings. We will publish... or perish trying!", objectives = "Find a Sealed Letter to Neltharion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74291] = { id = 74291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blue is My Favorite Color", completion = "Let's get back to work.", objectives = "Speak to Kirygosa and then return to the Azure Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74292] = { id = 74292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deephollow Mysteries" }
quests[74293] = { id = 74293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Forgotten", description = "Viridia is confident that more dracthyr may slumber in these chambers, long forgotten amongst Neltharion's relics.", completion = "It warms my heart to see so many new arrivals. We will do our best to orient them to the changes since they were last awake.\n\nThank you, friend.", objectives = "Free dracthyr trapped in stasis within the Zskera Vaults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74294] = { id = 74294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keys You Need", description = "Can I trust you? These are the only keys we have. If we lose them, we can't open any locked doors.\n\nHere. Take them. Use them on the doors within this chamber. You look like a hero. Be bold! Throw those doors wide! You'll find glory or... um... something that is not glory but is still amazing! Just don't die.\n\nWe might find more, but we'll have to search the island to find them.", completion = "Be sure to not to lose those keys. Did I say that? I think I said that.", objectives = "Take the keys from Tacha at the Zskera Vaults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74295] = { id = 74295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
