quests[74352] = { id = 74352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whirling Zephyr" }
quests[74354] = { id = 74354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifacts Abound", description = "It is... certainly bizarre to see Sindragosa, real in all but the flesh.\n\nLook, I appreciate that you have both come all this way for me. The Isles sounds delightful, but I have dedicated many years to cleaning up Winterspring. I am not about to leave a job unfinished. Magic is abound and unfortunately not all good.\n\nIf you would like to help, The Hidden Grove is next on my list. Therein lie ruins of totems that still emanate with some sort of magic. Will you collect pieces of them?", progress = "And that one, I suppose, is harmless enough...", completion = "Thank you. Now, to take a closer look at these.", objectives = "Collect 5 Totemic Ruins from the Hidden Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74355] = { id = 74355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primordial Embellishment", description = "How remarkable! You can affix such a variety of special gems to enhance its power!\n\nYou should journey back into the Zskera Vaults and locate a Primordial Jeweler's Kit. Yes, that's what you'll need.\n\nCrafting gems of this type requires specialized tools. Once we have them, we can fully explore the ring's power! The mind reels with limitless possibilities...", progress = "Did you find it?", completion = "There's far more here than I expected! \n\nI never dreamt to see such wonders. With these tools, we could even craft another ring! Just in case you lose that one... or, say, want to give one to... \n\nOh, forgive me! I am presumptuous. It's just so... wonderful.", objectives = "Collect the Primordial Jeweler's Kit and the Primordial Anvil from the Zskera Vaults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74356] = { id = 74356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back with the Blues", description = "It seems I had a good idea.\n\nNow let us hope we can broach the subject of the Isles again. I am glad to see Haleh relaxed. She deserves it.", completion = "We shall have to find Haleh a hot springs here, too. \n\n<Sindragosa smiles.>", objectives = "Return to the Azure Archives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74357] = { id = 74357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74358] = { id = 74358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[74359] = { id = 74359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunder Siege", description = "We're not the only ones to have noticed the storms abating over the Forbidden Reach. \n\nOther interested parties have arrived too, looting everything they can and storing their spoils in chests. If they use Neltharion's old hoard chests, they're in for a surprise when the chests' enchantments lock them out. We'll need to clear out surrounding looters to break the chests' enchantments.\n\nSee if you can recover a stolen item, specifically my old journal. It's nowhere to be found.", progress = "Were you able to find it?", completion = "Thank you, {name}.\n\nMy world has changed so drastically since I last wrote in this. It will be an interesting read, given what I know now.", objectives = "Recover Atrenosh's Journal from chests within the Forbidden Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74374] = { id = 74374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Important Heirloom", description = "I can guide you in crafting your offering to the ancestors, but you will need two things:\n\nFirst, you need to know the basics! Arugi here can teach you how to cook if you don't already know.\n\nSecond, I need my old cookbook. We're going to make something truly special, a fusion of old Draenor and Azeroth, and I'm going to need it for reference. \n\nGo fetch my book from the inn, and we can get started.", progress = "Did you find my book? It's somewhere inside the inn.", completion = "Ah, here we are. It may not look like much, but this old thing made it through the Dark Portal! \n\nIt's a family heirloom from before the Horde. Unusual for an {race}, I know. My great grandmother, Cook Barasha, collected recipes from all the clans at each Kosh'harg. As I understand it, she didn't trust anyone else to get it right, so she wrote it all down! We have stories of her awesome stubbornness...\n\nEnough reminiscing! Time to get cooking! Hope you're ready, we have some work ahead of us.", objectives = "Learn the basics of cooking and retrieve Cook Torka's cookbook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74375] = { id = 74375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collating Their Research", description = "It no longer matters how the Sundered Flame got here; now we need to know why. What is in this vault that Sarkareth is after?\n\n{name}, while you are in their camp, look for notes, research papers, journals--anything you can find that might reveal their intentions. Please bring whatever you find to me.", progress = "Were you able to learn anything yet?", completion = "The information in these notes is... troubling, but it does not tell me why Sarkareth is trying to find and enter Aberrus.\n\nThe only way to know will be to catch up to him.", objectives = "Find out why the Sundered Flame expedition is in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74376] = { id = 74376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coalesced Storm Remnants", description = "The Primalist Researchers in the area will be interested in this for further study.", completion = "Fascinating! I'll relay my findings to the other researchers in Valdrakken.", objectives = "Bring the Coalesced Storm Remnants to Brendormi in the Primalist Tomorrow.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74377] = { id = 74377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capsize a Crab" }
quests[74378] = { id = 74378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm's Fury" }
quests[74379] = { id = 74379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Within Reach", description = "While we dracthyr were kept in stasis, the Spellsworn, ancient servants of Malygos the Spellweaver, were our wardens. However, despite being slain years ago, the late Aspect's forces are still loyal to him and his lasting directive to keep this island contained. They present a danger to any dracthyr still lost, wounded, or otherwise unaccounted for.\n\nScouts have reported the sighting of a rather large Spellsworn brute hunting for escaped dracthyr. This deadly pursuer must be dealt with.", completion = "Thank you, {class}. You have diminished the risk to our rescue and recovery operations around the Forbidden Reach.\n\nIt may be too late for some, but know that other sets of wings will be able to fly home because of your actions.", objectives = "Kill the Spellsworn Wingcatcher at the Old Weyrn Grounds in the Forbidden Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74381] = { id = 74381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Legacies", description = "Raszageth and her storms are gone, but our troubles are far from over.\n\nThe way to the Reach is clear again, and some of our allies have returned to establish a base camp. However, Sarkareth and the Sundered Flame have begun making their way there as well.\n\nWe need to secure the island. We would appreciate your aid.", progress = "Ah, an adventurer! Did Emberthal send you?", completion = "Thankfully, our enemies have not discovered our scouts. The Incarnates and the Sundered Flame are both formidable foes. I'm uncertain whether we'll be able to safely monitor them again without retribution.\n\nThe situation is heating up. Some of the dracthyr have already returned to the island, but they're going to need a lot of help building up their base of operations.\n\nYou're about to be very busy, friend.", objectives = "Speak to the Healing Wings Envoy at the Seat of the Aspects to learn about events in the Forbidden Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74382] = { id = 74382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Community Feast" }
quests[74389] = { id = 74389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filming the Caldera", description = "The arthropods in Caldera of the Menders are truly vicious. One of our gyrocopters went missing there!\n\nOur expedition sent a unmanned surveillance aircraft there, but it hasn't returned. Can you find the gyrocopter? You could use it to capture the Caldera's wildlife on camera?", completion = "Well done! Extensive photography makes our documentation complete!", objectives = "Fly over the Caldera of the Menders and capture local wildlife on your camera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74390] = { id = 74390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutal Prey", description = "This land is crawling with opportunities for a skilled hunter. We want you to join the hunt. \n\nSome threats are feral. Dare I say it, some are greatest threats are sentient and malevolent. If we all work together, we can make the Reach a safe haven, as it used to be.", completion = "I like how you deal with problems. I'm sure they got what they deserved.", objectives = "Hunt down elite creatures across the Forbidden Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74391] = { id = 74391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpooner's Challenge", description = "Say, have you noticed how good the fishing is around here? Dragonskull Island seems like it would have some great spots.\n\nWhy don't you go there and catch something for dinner? Be mindful, though. We still need to set some of our catch aside for later.", progress = "I can almost taste those fresh fish!", completion = "I've heard about \"fine dining.\" I don't quite know what that is, but I know we'll eat well tonight!", objectives = "Gather 3 Lunker Morsels from Lunkers in Dragonskull Island Fishing Hole.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74393] = { id = 74393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report: Battlefield Ruins", description = "Our situation is worse than we thought. \n\nTheir dominance of the air keeps us at a disadvantage. They plan on freeing their powerful Elder from Aberrus. Allowing them to accomplish this could result in us permanently forfeiting control of this area.\n\nSeek out Field Commander Ignax in the Battlefield Ruins and see what can be done to turn the tide of this battle. We will join you shortly.", completion = "It is good to see an ally out here in the field. We could use one right now.", objectives = "Find Field Commander Ignax in the Battlefield Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74394] = { id = 74394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
