quests[74415] = { id = 74415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Offering", description = "Now that we have everything on the list, you just have to put it all together, right? How hard could it be?\n\nUmm... I'm going to let you handle it, though. I'll watch.", progress = "Is your task complete?", completion = "You have done well. It is a rare thing for the ancestors to cross over and manifest before an offering. Yours must have been truly worthy. I hope Durak appreciates the honor that was just bestowed upon him, as well.\n\nWhen the om'gora is finished, you should pass on the messages you received for the others. I think he would appreciate it.\n\n<She offers you a quick wink.>", objectives = "Cook the orcish dishes and then place the Feast for the Ancestors at the offering stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
