quests[74432] = { id = 74432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zskera Vaults" }
quests[74433] = { id = 74433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning the Blade", description = "<This dagger, found buried in the chest of the giant worm Icebreaker, belonged to Saza. It is evident that Saza fought bravely, deeply wounding the monster before her death.\n\nThis blade should be brought back to the village to give her clan closure.>", progress = "That's... Saza's dagger. Why do you have her dagger? Oh...", completion = "<Jyrra sighs as you tell her the news, her eyes dulled by tears.>\n\nThank you for bringing this dagger back and for telling us of her bravery. Saza fought hard for her family. As I would too.\n\nI should have gone with you. If only...\n\nI'm sorry, {name}. I am in your debt. \n\n\n\nOh, I will miss you, little sister...", objectives = "Bring Saza's dagger to the Winterpelt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74436] = { id = 74436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm Warning", description = "Ah, {class}! I knew I would find you at the right place at the right time. \n\nThe elements do not just threaten the Dragon Isles in our current time, but also from beyond. Go to the Temporal Conflux and travel through the rift into the future the primalists have overrun.\n\nThere, speak to Soridormi. She will have more details for you when you arrive.", progress = "It is good to see you again.", completion = "We meet again, {name}. We have more need for your help, I'm afraid.", objectives = "Speak to Soridormi in the Primalist Future. The portal to the Primalist Future can be found at the Temporal Conflux in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74437] = { id = 74437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resisting the Storm", description = "The Primalists are growing in strength in this future timeline, despite our best efforts. If they overrun this valley and threaten the Temporal Conflux, they may become a problem for the rest of the timeways.\n\nWe are already protecting the timeways from enough threats.\n\nPush back on them, {name}. We need to keep this peril in check. Speak to Tarnormu to gather any supplies you might need.", progress = "We cannot let the Primalists become a threat to other periods in our history.", completion = "You have been an inspiration to the few forces that still remain, {class}. \n\nThe threat may be pushed back a little for now, but we must continue our vigil here so that the rest of the timeways are not in yet more dangers than before.", objectives = "Stock up on any necessary supplies and complete \"The Storm's Fury\" event in the Primalist Future.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[74440] = { id = 74440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windseeker Avash" }
quests[74441] = { id = 74441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eaglemaster Niraak" }
quests[74442] = { id = 74442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Dragon's Junk...", description = "Greetings! I am looking for items of power from my flight's past. \n\nWe have a history of great warriors and battle prowess, and I want to recover items that will help us reach that again.\n\nI heard you found these vaults. If you see anything of interest inside, could you show it to me?", progress = "Did you find anything interesting?", completion = "Oh, this is... definitely something?\n\nIt does not seem like it could be used as a weapon, but I suppose it is worth investigating. You never know.", objectives = "Locate an object for Voraxian within the Zskera Vaults.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
